50	/**
51	 * Shortens a path string if it exceeds maxLen, prioritizing the start and end segments.
52	 * Example: /path/to/a/very/long/file.txt -> /path/.../long/file.txt
53	 */
54	export function shortenPath(filePath: string, maxLen: number = 35): string {
55	  if (filePath.length <= maxLen) {
56	    return filePath;
57	  }
58	
59	  const simpleTruncate = () => {
60	    const keepLen = Math.floor((maxLen - 3) / 2);
61	    if (keepLen <= 0) {
62	      return filePath.substring(0, maxLen - 3) + '...';
63	    }
64	    const start = filePath.substring(0, keepLen);
65	    const end = filePath.substring(filePath.length - keepLen);
66	    return `${start}...${end}`;
67	  };
68	
69	  type TruncateMode = 'start' | 'end' | 'center';
70	
71	  const truncateComponent = (
72	    component: string,
73	    targetLength: number,
74	    mode: TruncateMode,
75	  ): string => {
76	    if (component.length <= targetLength) {
77	      return component;
78	    }
79	
80	    if (targetLength <= 0) {
81	      return '';
82	    }
83	
84	    if (targetLength <= 3) {
85	      if (mode === 'end') {
86	        return component.slice(-targetLength);
87	      }
88	      return component.slice(0, targetLength);
89	    }
90	
91	    if (mode === 'start') {
92	      return `${component.slice(0, targetLength - 3)}...`;
93	    }
94	
95	    if (mode === 'end') {
96	      return `...${component.slice(component.length - (targetLength - 3))}`;
97	    }
98	
99	    const front = Math.ceil((targetLength - 3) / 2);
100	    const back = targetLength - 3 - front;
101	    return `${component.slice(0, front)}...${component.slice(
102	      component.length - back,
103	    )}`;
104	  };
105	
106	  const parsedPath = path.parse(filePath);
107	  const root = parsedPath.root;
108	  const separator = path.sep;
109	
110	  // Get segments of the path *after* the root
111	  const relativePath = filePath.substring(root.length);
112	  const segments = relativePath.split(separator).filter((s) => s !== ''); // Filter out empty segments
113	
114	  // Handle cases with no segments after root (e.g., "/", "C:\") or only one segment
115	  if (segments.length <= 1) {
116	    // Fall back to simple start/end truncation for very short paths or single segments
117	    return simpleTruncate();
118	  }
119	
120	  const firstDir = segments[0];
121	  const lastSegment = segments[segments.length - 1];
122	  const startComponent = root + firstDir;
123	
124	  const endPartSegments = [lastSegment];
125	  let endPartLength = lastSegment.length;
126	
127	  // Iterate backwards through the middle segments
128	  for (let i = segments.length - 2; i > 0; i--) {
129	    const segment = segments[i];
130	    const newLength =
131	      startComponent.length +
132	      separator.length +
133	      3 + // for "..."
134	      separator.length +
135	      endPartLength +
136	      separator.length +
137	      segment.length;
138	
139	    if (newLength <= maxLen) {
140	      endPartSegments.unshift(segment);
141	      endPartLength += separator.length + segment.length;
142	    } else {
143	      break;
144	    }
145	  }
146	
147	  const components = [firstDir, ...endPartSegments];
148	  const componentModes: TruncateMode[] = components.map((_, index) => {
149	    if (index === 0) {
150	      return 'start';
151	    }
152	    if (index === components.length - 1) {
153	      return 'end';
154	    }
155	    return 'center';
156	  });
157	
158	  const separatorsCount = endPartSegments.length + 1;
159	  const fixedLen = root.length + separatorsCount * separator.length + 3; // ellipsis length
160	  const availableForComponents = maxLen - fixedLen;
161	
162	  const trailingFallback = () => {
163	    const ellipsisTail = `...${separator}${lastSegment}`;
164	    if (ellipsisTail.length <= maxLen) {
165	      return ellipsisTail;
166	    }
167	
168	    if (root) {
169	      const rootEllipsisTail = `${root}...${separator}${lastSegment}`;
170	      if (rootEllipsisTail.length <= maxLen) {
171	        return rootEllipsisTail;
172	      }
173	    }
174	
175	    if (root && `${root}${lastSegment}`.length <= maxLen) {
176	      return `${root}${lastSegment}`;
177	    }
178	
179	    if (lastSegment.length <= maxLen) {
180	      return lastSegment;
181	    }
182	
183	    // As a final resort (e.g., last segment itself exceeds maxLen), fall back to simple truncation.
184	    return simpleTruncate();
185	  };
186	
187	  if (availableForComponents <= 0) {
188	    return trailingFallback();
189	  }
190	
191	  const minLengths = components.map((component, index) => {
192	    if (index === 0) {
193	      return Math.min(component.length, 1);
194	    }
195	    if (index === components.length - 1) {
196	      return component.length; // Never truncate the last segment when possible.
197	    }
198	    return Math.min(component.length, 1);
199	  });
200	
201	  const minTotal = minLengths.reduce((sum, len) => sum + len, 0);
202	  if (availableForComponents < minTotal) {
203	    return trailingFallback();
204	  }
205	
206	  const budgets = components.map((component) => component.length);
207	  let currentTotal = budgets.reduce((sum, len) => sum + len, 0);
208	
209	  const pickIndexToReduce = () => {
210	    let bestIndex = -1;
211	    let bestScore = -Infinity;
212	    for (let i = 0; i < budgets.length; i++) {
213	      if (budgets[i] <= minLengths[i]) {
214	        continue;
215	      }
216	      const isLast = i === budgets.length - 1;
217	      const score = (isLast ? 0 : 1_000_000) + budgets[i];
218	      if (score > bestScore) {
219	        bestScore = score;
220	        bestIndex = i;
221	      }
222	    }
223	    return bestIndex;
224	  };
225	
226	  while (currentTotal > availableForComponents) {
227	    const index = pickIndexToReduce();
228	    if (index === -1) {
229	      return trailingFallback();
230	    }
231	    budgets[index]--;
232	    currentTotal--;
233	  }
234	
235	  const truncatedComponents = components.map((component, index) =>
236	    truncateComponent(component, budgets[index], componentModes[index]),
237	  );
238	
239	  const truncatedFirst = truncatedComponents[0];
240	  const truncatedEnd = truncatedComponents.slice(1).join(separator);
241	  const result = `${root}${truncatedFirst}${separator}...${separator}${truncatedEnd}`;
242	
243	  if (result.length > maxLen) {
244	    return trailingFallback();
245	  }
246	
247	  return result;
248	}
